import { envOrDie, SpaStack } from '@wolsok/spa-cdk-stack';
import { App, RemovalPolicy, Tags } from 'aws-cdk-lib';
import { CacheControl, Source } from 'aws-cdk-lib/aws-s3-deployment';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pagesByDepth, prerenderedPages } from './prerendered-pages';

const buildOutputPath = 'dist/apps/portfolio';

// Each prerendered page is at <page>/index.html, but CloudFront in front of
// S3 resolves no folder index: /privacy would fall back to the home page.
// So every page, nested ones such as /blog/<slug> too, is uploaded once more
// under its bare path, below.
const pages = prerenderedPages(buildOutputPath);

const app = new App();

const stackName = 'Portfolio';
const stack = new SpaStack(app, stackName, {
  env: {
    region: 'eu-central-1',
    account: '088632064895',
  },
  buildOutputPath,
  domainName: 'wolsok.de',
  bucketRemovalPolicy: RemovalPolicy.DESTROY,
  // Crawlers and AdSense read these by name; a page changes with each release.
  noCacheFiles: [
    'ads.txt',
    'app-ads.txt',
    'robots.txt',
    'sitemap.xml',
    'favicon.ico',
    ...pages.map((page) => `${page}/index.html`),
  ],
});

// One upload per depth: in a single one the file `blog` would block the
// folder `blog/` of `blog/<slug>` (see pagesByDepth).
for (const group of pagesByDepth(pages)) {
  stack.spa.addExtraAssets(
    group.map((page) =>
      Source.data(
        page,
        readFileSync(join(buildOutputPath, page, 'index.html'), 'utf8')
      )
    ),
    CacheControl.noCache(),
    'text/html; charset=utf-8'
  );
}

const tags: Tags = Tags.of(app);
tags.add('app', 'Portfolio');
tags.add('version', envOrDie('RELEASE_VERSION'));
import { readdirSync } from 'node:fs';
import { join } from 'node:path';

const PAGE_FILE = 'index.html';

/**
 * The prerendered pages below a build output: every folder, at any depth,
 * that holds an `index.html` (`career`, `blog/<slug>`), as its path from
 * the root with `/` between the segments. The root's own `index.html` is
 * the home page, which CloudFront already serves, so it is not listed.
 */
export function prerenderedPages(root: string, prefix = ''): string[] {
  return readdirSync(join(root, prefix), { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .flatMap((entry) => {
      const page = prefix ? `${prefix}/${entry.name}` : entry.name;
      const own = readdirSync(join(root, page)).includes(PAGE_FILE)
        ? [page]
        : [];
      return [...own, ...prerenderedPages(root, page)];
    });
}

/**
 * The pages grouped by their depth (`career`, `blog` before
 * `blog/<slug>`), one upload each: a deployment unpacks all its sources
 * into one folder, where the bare-path file `blog` leaves no room for the
 * folder `blog/` that `blog/<slug>` needs (`Not a directory`). Within one
 * depth no page can be the folder of another.
 */
export function pagesByDepth(pages: readonly string[]): string[][] {
  const groups = new Map<number, string[]>();
  for (const page of pages) {
    const depth = page.split('/').length;
    const group = groups.get(depth) ?? [];
    group.push(page);
    groups.set(depth, group);
  }
  return [...groups.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, group]) => group);
}
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pagesByDepth, prerenderedPages } from './prerendered-pages';

describe('prerenderedPages', () => {
  let root: string;

  function file(path: string): void {
    mkdirSync(join(root, path, '..'), { recursive: true });
    writeFileSync(join(root, path), '');
  }

  beforeEach(() => {
    root = mkdtempSync(join(tmpdir(), 'portfolio-'));
  });

  afterEach(() => rmSync(root, { recursive: true, force: true }));

  it('lists every folder with an index.html, nested ones too', () => {
    file('index.html');
    file('career/index.html');
    file('blog/index.html');
    file('blog/bacteria-wars-turn-relay/index.html');
    file('blog/bacteria-wars-turn-relay/nat-walls.svg');
    file('media/font.woff2');

    expect(prerenderedPages(root).sort()).toEqual([
      'blog',
      'blog/bacteria-wars-turn-relay',
      'career',
    ]);
  });

  it('finds a page below a folder that is none', () => {
    file('docs/guide/index.html');

    expect(prerenderedPages(root)).toEqual(['docs/guide']);
  });
});

describe('pagesByDepth', () => {
  const PAGES = [
    'career',
    'blog',
    'blog/bacteria-wars-turn-relay',
    'privacy',
    'docs/a/b',
    'blog/second-post',
  ];

  it('groups the pages by depth, shallowest first', () => {
    expect(pagesByDepth(PAGES)).toEqual([
      ['career', 'blog', 'privacy'],
      ['blog/bacteria-wars-turn-relay', 'blog/second-post'],
      ['docs/a/b'],
    ]);
  });

  it('never puts a page beside a page below it, as one upload unpacks them into one folder', () => {
    for (const group of pagesByDepth(PAGES)) {
      for (const page of group) {
        expect(group.filter((other) => other.startsWith(`${page}/`))).toEqual(
          []
        );
      }
    }
  });

  it('has no group for no pages', () => {
    expect(pagesByDepth([])).toEqual([]);
  });
});
