  const staging = asset.node.tryFindChild('Stage');
  if (!(staging instanceof AssetStaging)) {
    return undefined;
  }
  const folder = staging.absoluteStagedPath;
  return existsSync(folder) && statSync(folder).isDirectory()
    ? folder
    : undefined;
}

